/bin/bash -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict'
import { readFileSync } from 'node:fs'

const origin = 'http://127.0.0.1:3100'
const manifest = JSON.parse(readFileSync('.next/prerender-manifest.json', 'utf8'))
assert.equal(manifest.routes['/news'].initialRevalidateSeconds, 3600)
assert.equal(manifest.routes['/news'].response, 'complete')
assert.equal(manifest.routes['/preview'].response, 'initial')
assert.equal(manifest.routes['/preview'].experimentalPPR, true)
const shell = readFileSync('.next/server/app/preview.html', 'utf8')
assert.match(shell, /Editor preview/)
assert.match(shell, /Loading draft/)
assert.doesNotMatch(shell, /Untitled draft/)
console.log('PASS: newsroom revalidates hourly; preview prerenders only its shell.')

for (const path of ['/', '/news']) {
  const response = await fetch(origin + path)
  assert.equal(response.status, 200)
  const body = await response.text()
  if (path === '/news') {
    assert.match(body, /City council approves new park/)
    assert.match(body, /Night market opens Friday/)
    assert.match(response.headers.get('cache-control'), /s-maxage=3600/)
  } else {
    assert.match(body, /Northstar Publishing/)
  }
}
console.log('PASS: home and newsroom serve successfully, with hourly newsroom cache headers.')

const titles = ['Editor-A-unique-draft', 'Editor-B-unique-draft']
async function checkPreview(title) {
  const response = await fetch(origin + '/preview', {
    headers: title ? { cookie: "'`draft-title=${title}` } : {},
  })
  assert.equal(response.status, 200)
  assert.match(response.headers.get('"'cache-control'), /private/)
  assert.match(response.headers.get('cache-control'), /no-store/)
  const body = await response.text()
  assert.ok(body.includes("'`<p>${title ?? '"'Untitled draft'}</p>"'`))
  for (const other of titles.filter(value => value !== title)) {
    assert.ok(!body.includes(other), `Preview leaked ${other}`)
  }
}
await checkPreview(undefined)
await Promise.all(titles.map(checkPreview))
await checkPreview(undefined)
await checkPreview(titles[0])
console.log('"'PASS: distinct editor cookies stay isolated across concurrent and repeated requests; missing cookies use Untitled draft.')
NODE"
